import{at as e,it as t,t as n,vt as r}from"./chunks/framework.B8HA7oqK.js";var i=JSON.parse(`{"title":"Mux.Cool Protocol","description":"","frontmatter":{},"headers":[],"relativePath":"en/development/protocols/muxcool.md","filePath":"en/development/protocols/muxcool.md","lastUpdated":1769207840000}`),a={name:`en/development/protocols/muxcool.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="mux-cool-protocol" tabindex="-1">Mux.Cool Protocol <a class="header-anchor" href="#mux-cool-protocol" aria-label="Permalink to “Mux.Cool Protocol”">​</a></h1><p>The Mux.Cool protocol is a multiplexing transport protocol used to transmit multiple independent data streams within a single established data stream.</p><h2 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to “Version”">​</a></h2><p>The current version is 1 Beta.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to “Dependencies”">​</a></h2><h3 id="underlying-protocol" tabindex="-1">Underlying Protocol <a class="header-anchor" href="#underlying-protocol" aria-label="Permalink to “Underlying Protocol”">​</a></h3><p>Mux.Cool must run on top of an established reliable data stream.</p><h2 id="communication-process" tabindex="-1">Communication Process <a class="header-anchor" href="#communication-process" aria-label="Permalink to “Communication Process”">​</a></h2><p>A Mux.Cool connection can transmit multiple sub-connections. Each sub-connection has a unique ID and status. The transmission process consists of Frames, and each frame is used to transmit data for a specific sub-connection.</p><h3 id="client-behavior" tabindex="-1">Client Behavior <a class="header-anchor" href="#client-behavior" aria-label="Permalink to “Client Behavior”">​</a></h3><p>When there is a need for a connection and no existing connection is available, the client initiates a new connection to the server, hereafter referred to as the &quot;main connection&quot;.</p><ol><li>A main connection can be used to send multiple sub-connections. The client can decide the number of sub-connections the main connection can carry.</li><li>For a new sub-connection, the client must send the status <code>New</code> to notify the server to establish the sub-connection, and then use the status <code>Keep</code> to transmit data.</li><li>When a sub-connection ends, the client sends the <code>End</code> status to notify the server to close the sub-connection.</li><li>The client can decide when to close the main connection but must ensure the server also maintains the connection.</li><li>The client can use the <code>KeepAlive</code> status to prevent the server from closing the main connection.</li></ol><h3 id="server-behavior" tabindex="-1">Server Behavior <a class="header-anchor" href="#server-behavior" aria-label="Permalink to “Server Behavior”">​</a></h3><p>When the server receives a new sub-connection, it should handle it as a normal connection.</p><ol><li>When receiving the <code>End</code> status, the server can close the uplink connection to the target address.</li><li>In the server&#39;s response, the same ID as the request must be used to transmit the sub-connection&#39;s data.</li><li>The server cannot use the <code>New</code> status.</li><li>The server can use the <code>KeepAlive</code> status to prevent the client from closing the main connection.</li></ol><h2 id="transmission-format" tabindex="-1">Transmission Format <a class="header-anchor" href="#transmission-format" aria-label="Permalink to “Transmission Format”">​</a></h2><p>Mux.Cool uses a symmetric transmission format, meaning the client and server send and receive data in the same format.</p><h3 id="frame-format" tabindex="-1">Frame Format <a class="header-anchor" href="#frame-format" aria-label="Permalink to “Frame Format”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">L bytes</th><th style="text-align:left;">X bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Metadata Length L</td><td style="text-align:left;">Metadata</td><td style="text-align:left;">Extra Data</td></tr></tbody></table><h3 id="metadata" tabindex="-1">Metadata <a class="header-anchor" href="#metadata" aria-label="Permalink to “Metadata”">​</a></h3><p>There are several types of metadata. All types of metadata include ID and Opt items, with meanings as follows:</p><ul><li>ID: Unique identifier for the sub-connection <ul><li>For general Mux sub-connections, the ID accumulates starting from 1.</li><li>For <a href="https://github.com/XTLS/Xray-core/blob/main/common/xudp/xudp.go" target="_blank" rel="noreferrer">Single XUDP</a> implemented by Xray, the ID is always 0.</li></ul></li><li>Opt: <ul><li>D(0x01): Has extra data</li></ul></li></ul><p>When option Opt(D) is enabled, the extra data format is as follows:</p><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">X-2 bytes</th></tr></thead><tbody><tr><td style="text-align:left;">Length X-2</td><td style="text-align:left;">Data</td></tr></tbody></table><h3 id="new-sub-connection-new" tabindex="-1">New Sub-connection (New) <a class="header-anchor" href="#new-sub-connection-new" aria-label="Permalink to “New Sub-connection (New)”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">A bytes</th><th style="text-align:left;">8 bytes</th></tr></thead><tbody><tr><td style="text-align:left;">ID</td><td style="text-align:left;">0x01</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Network Type N</td><td style="text-align:left;">Port</td><td style="text-align:left;">Address Type T</td><td style="text-align:left;">Address A</td><td style="text-align:left;">Global ID (XUDP)</td></tr></tbody></table><p>Where:</p><ul><li>Network Type N: <ul><li>0x01: TCP, indicating that the traffic of the current sub-connection should be sent to the target via TCP.</li><li>0x02: UDP, indicating that the traffic of the current sub-connection should be sent to the target via UDP.</li></ul></li><li>Address Type T: <ul><li>0x01: IPv4</li><li>0x02: Domain name</li><li>0x03: IPv6</li></ul></li><li>Address A: <ul><li>When T = 0x01, A is a 4-byte IPv4 address;</li><li>When T = 0x02, A is a 1-byte length (L) + L bytes of domain name;</li><li>When T = 0x03, A is a 16-byte IPv6 address;</li></ul></li><li>Global ID (XUDP): <ul><li>The client calculates a global unique ID for the UDP source 2-tuple. The server uses this to ensure that when XUDP reconnects after disconnection, it still uses the same port to communicate with the target.</li></ul></li></ul><p>When creating a new sub-connection, if Opt(D) is enabled, the data carried in this frame needs to be sent to the target host.</p><h3 id="keep-sub-connection-keep" tabindex="-1">Keep Sub-connection (Keep) <a class="header-anchor" href="#keep-sub-connection-keep" aria-label="Permalink to “Keep Sub-connection (Keep)”">​</a></h3><p>TCP</p><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th></tr></thead><tbody><tr><td style="text-align:left;">ID</td><td style="text-align:left;">0x02</td><td style="text-align:left;">Option Opt</td></tr></tbody></table><p>UDP</p><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">A bytes</th></tr></thead><tbody><tr><td style="text-align:left;">ID</td><td style="text-align:left;">0x02</td><td style="text-align:left;">Option Opt</td><td style="text-align:left;">Network Type N</td><td style="text-align:left;">Port</td><td style="text-align:left;">Address Type T</td><td style="text-align:left;">Address A</td></tr></tbody></table><p>When keeping a sub-connection, if Opt(D) is enabled, the data carried in this frame needs to be sent to the target host. XUDP adds the UDP address after Opt(D), formatted the same as in &quot;New Sub-connection&quot;, but without the Global ID.</p><h3 id="end-sub-connection-end" tabindex="-1">End Sub-connection (End) <a class="header-anchor" href="#end-sub-connection-end" aria-label="Permalink to “End Sub-connection (End)”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th></tr></thead><tbody><tr><td style="text-align:left;">ID</td><td style="text-align:left;">0x03</td><td style="text-align:left;">Option Opt</td></tr></tbody></table><p>When closing a sub-connection, if Opt(D) is enabled, the data carried in this frame needs to be sent to the target host.</p><h3 id="keep-connection-keepalive" tabindex="-1">Keep Connection (KeepAlive) <a class="header-anchor" href="#keep-connection-keepalive" aria-label="Permalink to “Keep Connection (KeepAlive)”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">2 bytes</th><th style="text-align:left;">1 byte</th><th style="text-align:left;">1 byte</th></tr></thead><tbody><tr><td style="text-align:left;">ID</td><td style="text-align:left;">0x04</td><td style="text-align:left;">Option Opt</td></tr></tbody></table><p>When keeping the connection:</p><ul><li>If Opt(D) is enabled, the data carried in this frame must be discarded.</li><li>The ID can be a random value.</li></ul><h2 id="application" tabindex="-1">Application <a class="header-anchor" href="#application" aria-label="Permalink to “Application”">​</a></h2><p>The Mux.Cool protocol is independent of the underlying protocol. Theoretically, any reliable stream connection can be used to transmit Mux.Cool protocol data.</p><p>In target-oriented protocols like Shadowsocks and VMess, a specified address must be included when the connection is established. To maintain compatibility, the Mux.Cool protocol specifies the address as &quot;v1.mux.cool&quot;. That is, when the target address of the main connection matches this, Mux.Cool forwarding is performed; otherwise, forwarding is performed in the traditional way. (Note: This is an internal marker within the program; VMess and VLESS do not send the &quot;v1.mux.cool&quot; address in the data packet.)</p>`,45)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};